def search(root, target):
    stack = [root]
    while stack:
        node = stack.pop()
        if node is None:
            continue
        if node['value'] == target:
            return True
        if target < node['value']:
            stack.append(node['right'])
            stack.append(node['left'])
        else:
            stack.append(node['left'])
            stack.append(node['right'])
    return False

def search_generator(root, target):
    stack = [root]
    while stack:
        node = stack.pop()
        if node is None:
            continue
        if node['value'] == target:
            yield True
            return
        if target < node['value']:
            stack.append(node['right'])
            stack.append(node['left'])
        else:
            stack.append(node['left'])
            stack.append(node['right'])

# Test
root = {'value': 50, 'left': {'value': 30, 'left': None, 'right': None}, 'right': {'value': 70, 'left': None, 'right': None}}
print(search(root, 70))
print(next(search_generator(root, 70), False))

