def serialize(root):
    if root is None:
        return 'None'
    return str(root.data) + ',' + serialize(root.left) + ',' + serialize(root.right)

def deserialize(data):
    def helper(values):
        val = next(values)
        if val == 'None':
            return None
        node = Node(int(val))
        node.left = helper(values)
        node.right = helper(values)
        return node
    values = iter(data.split(','))
    return helper(values)
